cssCode:
.glow-particle { 
  position: absolute; 
  width: 8px; height: 8px; 
  background: #ff007f; 
  border-radius: 50%; 
  box-shadow: 0 0 15px #ff007f, 0 0 30px #ff007f; 
  animation: floatUp 4s infinite linear; 
}
@keyframes floatUp { 
  0% { transform: translateY(0) scale(1); opacity: 0; } 
  50% { opacity: 1; } 
  100% { transform: translateY(-150px) scale(0); opacity: 0; } 
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;overflow:hidden;background:transparent;';
for(let i=0; i<20; i++) {
  const p = document.createElement('div');
  p.className = 'glow-particle';
  p.style.left = Math.random() * 100 + '%';
  p.style.top = Math.random() * 100 + '%';
  p.style.animationDelay = (Math.random() * 3) + 's';
  c.appendChild(p);
}
